				intent = strategy.TruncateDescription(lines[0], maxIntentDisplayLength)
			}
		}
		fmt.Fprintf(&sb, "Intent: %s\n", intent)
		sb.WriteString("Outcome: (not generated)\n")
	}

	// Verbose: add commit message, learnings, friction, files, and prompts
	if verbose || full {
		// AI Summary details (learnings, friction, open items)
		if meta.Summary != nil {
			formatSummaryDetails(&sb, meta.Summary)
		}

		// Commit message section (only if available)
		if commitMessage != "" {
			sb.WriteString("\n")
			fmt.Fprintf(&sb, "Commit: %s\n", commitMessage)
		}

		sb.WriteString("\n")

		// Files section
		if len(meta.FilesTouched) > 0 {
			fmt.Fprintf(&sb, "Files: (%d)\n", len(meta.FilesTouched))
			for _, file := range meta.FilesTouched {
				fmt.Fprintf(&sb, "  - %s\n", file)
			}
		} else {
			sb.WriteString("Files: (none)\n")
		}

		sb.WriteString("\n")

		// Prompts section (using scoped prompts, or fall back to stored prompts for backwards compat)
		sb.WriteString("Prompts:\n")
		switch {
		case len(scopedPrompts) > 0:
			sb.WriteString(strings.Join(scopedPrompts, "\n\n---\n\n"))
			sb.WriteString("\n")
		case result.Prompts != "":
			// Backwards compatibility: use stored prompts if no transcript available
			sb.WriteString(result.Prompts)
			sb.WriteString("\n")
		default:
			sb.WriteString("  (none)\n")
		}
	}

	// Full: add transcript
	if full {
		sb.WriteString("\n")
		sb.WriteString("Transcript:\n")
		if len(result.Transcript) > 0 {
			sb.Write(result.Transcript)
			sb.WriteString("\n")
		} else {
			sb.WriteString("  (none)\n")
		}
	}

