// formatTranscriptSection formats transcript bytes into a human-readable string.
// It parses the JSONL transcript and formats it using the condensed format.
// The fallbackPrompts are used for backwards compatibility when transcript parsing fails.
func formatTranscriptSection(transcriptBytes []byte, fallbackPrompts string) string {
	if len(transcriptBytes) == 0 {
		if fallbackPrompts != "" {
			return fallbackPrompts + "\n"
		}
		return "  (none)\n"
	}

	condensed, err := summarise.BuildCondensedTranscriptFromBytes(transcriptBytes)
	if err != nil || len(condensed) == 0 {
		if fallbackPrompts != "" {
			return fallbackPrompts + "\n"
		}
		return "  (failed to parse transcript)\n"
	}

	input := summarise.Input{Transcript: condensed}
	return summarise.FormatCondensedTranscript(input)
}

